import{_ as c,r as o,o as d,c as l,e as s,a as r,s as n}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Дочерние темы - October CMS - 3.x","titleTemplate":false,"description":"Переопределяйте тему, создавая дочернюю версию.","frontmatter":{"subtitle":"Переопределяйте тему, создавая дочернюю версию."},"headers":[{"level":2,"title":"Файл блокировки темы","slug":"фаил-блокировки-темы","link":"#фаил-блокировки-темы","children":[]},{"level":2,"title":"Создание новой дочерней темы","slug":"создание-новои-дочернеи-темы","link":"#создание-новои-дочернеи-темы","children":[]}],"relativePath":"3.x/ru/cms/themes/child-themes.md","filePath":"3.x/ru/cms/themes/child-themes.md"}'),p={name:"3.x/ru/cms/themes/child-themes.md"};function h(i,e,m,_,g,u){const a=o("pre-heading"),t=o("post-heading");return d(),l("div",null,[s(a),e[0]||(e[0]=r("h1",null,"Дочерние темы",-1)),s(t),e[1]||(e[1]=n(`<p>Дочерние темы обеспечивают возможность наследования тем. Хорошим примером использования является ситуация, когда у вас есть сторонняя тема или тема в режиме «только для чтения». Дочерняя тема ссылается на родительскую и использует её в качестве резервного источника.</p><p>Если страница с именем <code>home.htm</code> существует в родительской теме, но отсутствует в дочерней, она обрабатывается так, как если бы она существовала: URL активен, и вы можете открыть страницу как обычно. При сохранении страницы в панели администрирования в дочерней теме создаётся новый файл, переопределяющий содержимое.</p><p>Чтобы включить эту функцию для темы, перейдите в <strong>Настройки → Фронтенд-тема</strong>, выберите <strong>Редактировать свойства</strong> и выберите родительскую тему из выпадающего списка <strong>Родительская тема</strong>.</p><h2 id="фаил-блокировки-темы"><a href="#фаил-блокировки-темы" class="header-anchor">#</a> Файл блокировки темы</h2><p>При установке темы от стороннего разработчика через Composer важно учитывать, что при обновлении темы все файлы могут быть перезаписаны. Это может привести к потере любых внесённых в тему изменений. В качестве защитного механизма в тему включается файл <code>.themelock</code>, который защищает тему от изменений, которые могут быть утрачены при обновлении системы.</p><p>Когда файл <code>.themelock</code> присутствует в директории темы:</p><ul><li>Тема может быть выбрана только в качестве родительской</li><li>Тема не отображается в интерфейсе панели администрирования</li><li>Тема не может быть выбрана как активная</li></ul><h2 id="создание-новои-дочернеи-темы"><a href="#создание-новои-дочернеи-темы" class="header-anchor">#</a> Создание новой дочерней темы</h2><p>Команда <code>theme:copy</code> может использоваться для создания новых тем, включая дочерние. Следующая команда создаёт новую тему <code>demo-copy</code> из исходной темы <code>demo</code> путём копирования директории и её содержимого. Файл <code>.themelock</code> будет удалён в процессе копирования.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan theme:copy demo demo-copy
</code></pre></div><p>Чтобы создать дочернюю тему, наследующую родительскую, укажите опцию <code>--child</code>.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan theme:copy demo demo-child <span class="token parameter variable">--child</span>
</code></pre></div>`,12))])}const x=c(p,[["render",h]]);export{v as __pageData,x as default};
